  ('okr_r1k_profit', null, 'Double profitability while funding the growth plan', 'So growth is fundable from its own success.', 'd_w6x3s5h', null, '5bf3a5f4-ed2e-4ef7-b193-d473d19e2312', '["5bf3a5f4-ed2e-4ef7-b193-d473d19e2312"]'::jsonb, 'percent', 4, 8, '%', 'up', '{"type": "monthly", "day": 5}'::jsonb, '2026-10-01', '2027-12-31', 6, 'e4040e6c-a085-431b-8bf2-d5eb8a8229ad', 'objective', null, false, null, null, '[]'::jsonb, '[]'::jsonb, null, null, true, '', null, false, false, '', 'active', null),
  ('okr_r1k_profit_gm', 'okr_r1k_profit', 'Gross profit — the margin cushion that lets the engines launch without starving the core business', 'Profitability is cross-functional; this is the one lever that’s Finance’s alone.', null, null, '5bf3a5f4-ed2e-4ef7-b193-d473d19e2312', '["5bf3a5f4-ed2e-4ef7-b193-d473d19e2312"]'::jsonb, 'percent', 40, 43, '%', 'up', '{"type": "monthly", "day": 5}'::jsonb, '2026-10-01', '2027-12-31', 0, 'e4040e6c-a085-431b-8bf2-d5eb8a8229ad', 'objective', null, false, null, null, '[]'::jsonb, '[]'::jsonb, null, null, true, '', null, false, false, '', 'active', null),
  ('okr_r1k_ksa', null, 'Extend the why into Saudi Arabia', 'Not a separate bet — the same structure mirrored once the UAE tree is finalised. Builds on prior KSA OKR work.', 'dept_54db1160', 'd_xuy36kr', '45ef436c-842b-441c-bae1-83038b211328', '["45ef436c-842b-441c-bae1-83038b211328"]'::jsonb, 'currency', 0, 6000000, 'SAR', 'up', '{"type": "monthly", "day": 5}'::jsonb, '2026-10-01', '2027-12-31', 7, 'e4040e6c-a085-431b-8bf2-d5eb8a8229ad', 'objective', null, false, null, null, '[]'::jsonb, '[]'::jsonb, null, null, true, '', null, false, true, 'Mirror the UAE structure under this once the UAE tree is final; add a Q4 checkpoint rather than one annual number.', 'active', null)
