-- ═══ Bridge v4 — seed: the Road to 1,000 OKR tree (BloomingBox OKR Proposal v1.2, 15 Sep 2026) ═══
-- Run ONCE, after migration 2026-10-02_v400_okr_v4.sql and after BOTH frontends run build v166+.
-- Idempotent: every row has a fixed id (okr_r1k_*) and is inserted with ON CONFLICT DO NOTHING; re-running adds nothing.
-- Nothing existing is touched: no update, no delete. Existing KPIs are linked afterwards from the app (Link KPI).
-- Owners: matched by name to Bridge users. “Sami”, “Dee”, “Ilayda”, “Leadership / People” and “?” have no Bridge user →
--         saved as “Owner to be decided” with a needs-decision note. “Nihad?” → Nihad, flagged for confirmation.
do $$ begin
  if not exists (select 1 from information_schema.columns where table_schema='public' and table_name='okrs' and column_name='kind') then
    raise exception 'Run migration 2026-10-02_v400_okr_v4.sql first (okrs.kind is missing)'; end if;
end $$;

on conflict (id) do nothing;

-- activity trail: one 'Created' entry per new row (skipped for rows that already existed)
select 'okl_seed_'||o.id, o.id, 'e4040e6c-a085-431b-8bf2-d5eb8a8229ad', 'Created objective', jsonb_build_object('source','Road to 1,000 proposal v1.2 seed'), now()
from public.okrs o where o.id like 'okr_r1k_%' and not exists (select 1 from public.okr_logs l where l.id='okl_seed_'||o.id);

-- sanity: what landed
select kind, state, count(*) from public.okrs where id like 'okr_r1k_%' group by 1,2 order by 1,2;